{
  "summary": "The Clean Architecture audit reveals a critical breakdown in dependency directionality. Six major violations span all architectural layers, where inner circles (Domain, Application) and even Infrastructure components are importing from outer layers (Presentation), completely inverting the intended dependency flow. This architectural inversion will cause severe maintenance difficulties and tightly coupled, untestable code.",
  "rationales": [
    {
      "violation_id": "main->presentation.api",
      "why_it_matters": "Application-layer 'main' importing from Presentation breaks the core dependency rule: inner layers must never depend on outer layers, leading to spaghetti dependencies and increased maintenance cost.",
      "prescribed_fix": "Define a 'Startup' or 'Entrypoint' port/interface in the Presentation layer, with 'main' holding a reference to it via dependency injection rather than direct import."
    },
    {
      "violation_id": "main->infrastructure.database",
      "why_it_matters": "Application-layer 'main' reaching directly into Infrastructure bypasses approved abstraction layers, creating maintenance overhead and violating clean architecture principles.",
      "prescribed_fix": "Introduce a 'Configuration' or 'Bootstrap' port in the Application layer that abstracts database initialization; implement the concrete adapter in infrastructure.database and inject it."
    },
    {
      "violation_id": "domain.fraud_checker->infrastructure.database",
      "why_it_matters": "Domain being contaminated with infrastructure imports violates the purity of business logic and makes it impossible to test core rules without a real database, breaking the fundamental separation of concerns.",
      "prescribed_fix": "Create a 'FraudRepository' port/interface inside the Domain layer, with infrastructure.database providing the concrete adapter implementation; inject the port into fraud_checker at runtime."
    },
    {
      "violation_id": "domain.payment_rule->presentation.controllers",
      "why_it_matters": "Domain logic depending on Presentation creates a circular dependency and exposes business rules to UI concerns, making the core engine fragile and tightly coupled to presentation code.",
      "prescribed_fix": "Remove all Presentation imports from Domain; let the Application or Presentation layers handle ResponseFormatter logic after the Domain returns raw data."
    },
    {
      "violation_id": "infrastructure.audit_logger->presentation.auth_middleware",
      "why_it_matters": "Infrastructure adapters should be agnostic of web frameworks, yet this import ties database-level logging directly to HTTP session contexts, reducing portability and increasing coupling.",
      "prescribed_fix": "Define a 'UserContextProvider' port in the Application layer that supplies authentication data; pass this context as method arguments to audit_logger instead of importing auth middleware."
    },
    {
      "violation_id": "presentation.order_routes->infrastructure.database",
      "why_it_matters": "Presentation directly accessing Infrastructure bypasses use cases and business logic, making testing difficult and locking web routes to specific database implementations.",
      "prescribed_fix": "Create a 'OrderService' or 'OrderUseCase' port in the Application layer, with infrastructure.database implementing the persistence details; have order_routes call the use case instead of the database directly."
    }
  ],
  "roadmap": [
    "HIGH: Resolve domain.fraud_checker->infrastructure.database and domain.payment_rule->presentation.controllers violations first—these threaten core business logic purity and are the hardest to remediate later.",
    "HIGH: Fix presentation.order_routes->infrastructure.database to establish proper flow from Presentation to Application, enabling testable, decoupled web endpoints.",
    "MEDIUM: Address infrastructure.audit_logger->presentation.auth_middleware by introducing a UserContext port in Application, decoupling cross-cutting concerns from web-specific code.",
    "MEDIUM: Resolve main->presentation.api and main->infrastructure.database in a coordinated refactor—consolidate bootstrapping and initialization logic behind proper entry-point abstractions."
  ]
}

